#!/bin/bash
# cross-configure FFmpeg (Kwiboo v4l2-request-n8.1) for FreeBSD aarch64 on the build host
cd /opt/bzdos/linux-work/ffmpeg/xbuild
S=/opt/bzdos/linux-work/ffmpeg/stage; SR=/opt/bzdos/sysroots/aarch64-15.1; M=/opt/bzdos/freebsd-media/sys/dev/media
PKG_CONFIG_LIBDIR=$S/lib/pkgconfig PKG_CONFIG_PATH= ../FFmpeg-4l2-request-n8.1/configure --prefix=/var/tmp/ffv4l2 --enable-cross-compile --arch=aarch64 --target-os=freebsd --cc="clang --target=aarch64-unknown-freebsd15.1 --sysroot=$SR" --ld="clang --target=aarch64-unknown-freebsd15.1 --sysroot=$SR -fuse-ld=lld" --ar=llvm-ar --nm=llvm-nm --ranlib=llvm-ranlib --strip=llvm-strip --pkg-config=pkg-config --disable-everything --disable-doc --disable-debug --disable-autodetect --disable-network --enable-libdrm --enable-libudev --enable-v4l2-request --extra-cflags="-I$M/shim -I$M/uapi" --extra-ldflags="-Wl,-rpath,/var/tmp/ffv4l2/udev/lib -L$S/lib" --enable-decoder=h264,mpeg2video,rawvideo --enable-parser=h264,mpegvideo --enable-demuxer=h264,mpegvideo,mov,matroska,mpegts,rawvideo --enable-muxer=rawvideo,null,mp4,framemd5,md5 --enable-encoder=rawvideo --enable-protocol=file,pipe --enable-bsf=h264_mp4toannexb,null --enable-filter=scale,format,null,hwdownload,hwmap,copy --enable-swscale --enable-hwaccel=h264_v4l2request,mpeg2_v4l2request
